"""Сетевое хранилище для существующих экранов Qt."""
import base64,csv,json,tempfile,uuid
from datetime import date
from pathlib import Path
from urllib.parse import urlparse,quote
from urllib.request import Request,urlopen
from urllib.error import HTTPError,URLError
from app.store import STATUS
from app.photo_pipeline import encode_photo

class RemoteStore:
    is_remote=True
    def __init__(self,url,transport=None):
        self.url=url.rstrip('/');p=urlparse(self.url)
        if p.scheme not in ('http','https') or not p.hostname or p.username or p.password or p.query or p.fragment:raise ValueError('Укажите адрес сервера, например http://192.168.1.10:8000.')
        self.token='';self.actor=None;self._snapshot=None;self._day=date.today().isoformat();self.transport=transport
        health=self.request('/health',auth=False)
        if not isinstance(health,dict) or health.get('ok') is not True or 'version' not in health:raise ValueError('По этому адресу не найден сервер НарядAI.')
        self._cache=tempfile.TemporaryDirectory(prefix='naryadai-client-');self.photos=Path(self._cache.name)
    def request(self,path,payload=None,auth=True,binary=False):
        if self.transport:return self.transport(path,payload,self.token if auth else '',binary)
        headers={'Content-Type':'application/json'}
        if auth:headers['Authorization']='Bearer '+self.token
        req=Request(self.url+path,data=json.dumps(payload,ensure_ascii=False).encode() if payload is not None else None,headers=headers,method='POST' if payload is not None else 'GET')
        try:
            with urlopen(req,timeout=8 if payload is None else 30) as r:
                data=r.read(36*1024*1024+1)
                if len(data)>36*1024*1024:raise OSError('Ответ сервера слишком большой.')
                return data if binary else json.loads(data)
        except HTTPError as e:
            try:message=json.loads(e.read()).get('detail','Сервер отклонил запрос.')
            except (ValueError,UnicodeError):message='Сервер отклонил запрос.'
            if not isinstance(message,str):message='Проверьте заполненные поля.'
            if e.code in (401,403):raise PermissionError(message) from None
            raise ValueError(message) from None
        except (URLError,TimeoutError,OSError):raise OSError('Нет связи с сервером. Проверьте интернет и адрес сервера. После простоя подключение может занять около минуты.') from None
        except (ValueError,UnicodeError):raise OSError('Сервер вернул неподдерживаемый ответ.') from None
    def authenticate(self,username,password,role):
        self.logout();r=self.request('/api/login',{'username':username,'password':password,'role':role},auth=False)
        self.token=r['token'];self.actor=r['user'];self._snapshot=None;return self.actor
    def logout(self):
        if self.token:
            try:self.request('/api/logout',{})
            except (OSError,ValueError,PermissionError):pass
        self.token='';self.actor=None;self._snapshot=None
        for p in self.photos.glob('*'):p.unlink(missing_ok=True)
    def refresh_snapshot(self,day=None):
        self._day=day or self._day
        snap=self.request('/api/snapshot?day='+quote(self._day,safe=''))
        self._snapshot=snap
        return snap
    def snapshot(self):
        if self._snapshot is None:self.refresh_snapshot()
        return self._snapshot
    def call(self,method,*args,photos=None,**kwargs):
        body={'args':list(args),'kwargs':kwargs,'request_id':uuid.uuid4().hex,'photos':photos or []}
        # Повторять мутацию автоматически не будем: при обрыве сначала обновить список.
        result=self.request('/api/call/'+method,body)['result']
        if method not in ('task','events','pauses','shift','free_slots','employee_status'):self._snapshot=None
        return result
    def tasks(self,actor):return self.snapshot()['tasks']
    def users(self,actor,workers_only=False):return [u for u in self.snapshot()['users'] if not workers_only or u['role']=='worker']
    def reports(self,actor):return self.snapshot()['reports']
    def task(self,actor,tid):
        return self.call('task',tid)
    def latest_report(self,actor,tid):return next((r for r in self.reports(actor) if r['task_id']==tid),None)
    def events(self,actor,tid):return self.call('events',tid)
    def pauses(self,actor,tid):return self.call('pauses',tid)
    def shift(self,actor,wid,day):
        s=self.snapshot()
        if day==s['day'] and str(wid) in s['shifts']:return s['shifts'][str(wid)]
        return self.call('shift',wid,day)
    def free_slots(self,actor,wid,day,at=None):
        s=self.snapshot()
        if at is None and day==s['day'] and str(wid) in s['free_slots']:return s['free_slots'][str(wid)]
        return self.call('free_slots',wid,day)
    def employee_status(self,actor,wid,at=None):return self.snapshot()['employee_status'].get(str(wid),'off')
    def metrics(self,actor):return self.snapshot()['metrics']
    def catalogs(self,actor):return self.request('/api/catalogs')
    def notifications(self,actor):return self.request('/api/notifications')['items']
    def analytics(self,actor,start,end,**filters):return self.call('analytics',start,end,**filters)
    def photos_for_task(self,actor,tid):return self.call('photos_for_task',tid)
    def create_task(self,actor,*,photo_sources=(),**kwargs):
        photos=[]
        for source in photo_sources:photos.append(encode_photo(source))
        return self.call('create_task',photos=photos,**kwargs)
    def submit(self,actor,tid,*,photo_sources,**kwargs):
        photos=[]
        for source in photo_sources:photos.append(encode_photo(source))
        return self.call('submit',tid,photos=photos,**kwargs)
    def ensure_photos(self,report):
        for name in report['photos']:
            if Path(name).name!=name:raise ValueError('Некорректное имя фото.')
            p=self.photos/name
            if not p.exists():p.write_bytes(self.request('/api/photos/'+quote(name,safe=''),binary=True))
    def export_reports(self,actor,path):
        self.refresh_snapshot()
        with open(path,'w',encoding='utf-8-sig',newline='') as f:
            writer=csv.writer(f,delimiter=';');writer.writerow(['Отчёт','Наряд','Работа','Сотрудник','Статус','Часы','Оценка мастера','Материалы, тг','Комментарий','Дата'])
            reports=[];offset=0
            while offset is not None:
                page=self.request('/api/reports?limit=200&offset='+str(offset));reports.extend(page['items']);offset=page['next_offset']
            for r in reports:
                values=[r['id'],r['task_id'],r['title'],r['worker_name'],STATUS[r['status']],r['hours'],r['score'],round(sum(m['quantity']*m['price'] for m in r['materials']),2),r['comment'],r['created']]
                writer.writerow(["'"+v if isinstance(v,str) and v.startswith(('=','+','-','@','\t','\r')) else v for v in values])

def _proxy(method):
    def invoke(self,actor,*args,**kwargs):return self.call(method,*args,**kwargs)
    return invoke

for _method in ('claim','reschedule','transition','review','add_user','set_active','reset_password','support_update_task','set_shift','reassign_task','change_priority','catalog_upsert','set_material_norm','set_employee_profile','start_downtime','end_downtime','assess_refusal','confirm_repeat','acknowledge_notification'):
    setattr(RemoteStore,_method,_proxy(_method))

"""PostgreSQL-адаптер для сохранения проверенных правил Store.
Все пользовательские значения передаются параметрами. Схема изолирована от Data API.
"""
import re,sqlite3,json,threading
from datetime import date,datetime
from decimal import Decimal
from zoneinfo import ZoneInfo
from contextlib import contextmanager
import psycopg
from psycopg.rows import dict_row
from psycopg_pool import ConnectionPool
from server.store import ServerStore

TABLES_WITH_IDS={'users','tasks','reports','events','pauses','sites','equipment','materials','defect_codes','brigades','work_norms','task_photos','task_assignments','brigade_memberships','equipment_downtimes','notification_outbox','task_refusals'}

class Row(dict):
    """Keep the cloud-1.4 wire format while PostgreSQL stores native types."""
    def __init__(self,values,json_columns=()):
        normalized={}
        for key,value in values.items():
            if key in json_columns:
                value=json.dumps(value,ensure_ascii=False)
            elif isinstance(value,datetime):
                if value.tzinfo is not None:value=value.astimezone(ZoneInfo('Asia/Qyzylorda')).replace(tzinfo=None)
                value=value.isoformat(timespec='seconds')
            elif isinstance(value,date):value=value.isoformat()
            elif isinstance(value,Decimal):value=float(value)
            normalized[key]=value
        super().__init__(normalized)
    def __getitem__(self,key):return list(self.values())[key] if isinstance(key,int) else super().__getitem__(key)

def postgres_sql(sql):
    """Преобразовать только известные внутренние SQLite-конструкции."""
    text=sql.strip().rstrip(';')
    if text.startswith(('PRAGMA','BEGIN IMMEDIATE')):return 'SELECT 1'
    ignored=text.upper().startswith('INSERT OR IGNORE')
    if ignored:text=re.sub(r'^INSERT OR IGNORE','INSERT',text,flags=re.I)+' ON CONFLICT DO NOTHING'
    # Не заменять вопросительные знаки внутри строковых/идентификаторных литералов.
    out=[];quote=None;i=0
    while i<len(text):
        ch=text[i]
        if quote:
            out.append(ch)
            if ch==quote:
                if i+1<len(text) and text[i+1]==quote:out.append(text[i+1]);i+=1
                else:quote=None
        elif ch in ('\"',"'"):quote=ch;out.append(ch)
        elif text[i:i+3]=='end' and (i==0 or not (text[i-1].isalnum() or text[i-1]=='_')) and (i+3==len(text) or not (text[i+3].isalnum() or text[i+3]=='_')):
            out.append('"end"');i+=2
        else:out.append('%s' if ch=='?' else ch)
        i+=1
    return ''.join(out)

def postgres_ddl(sql):
    sql=re.sub(r'\bINTEGER PRIMARY KEY(?: AUTOINCREMENT)?\b','BIGSERIAL PRIMARY KEY',sql)
    return re.sub(r'\bREAL\b','DOUBLE PRECISION',sql)

class Cursor:
    def __init__(self,cursor,lastrowid=None):self.cursor=cursor;self.lastrowid=lastrowid
    def _row(self,row):
        json_columns={column.name for column in self.cursor.description if column.type_code in (114,3802)}
        return Row(row,json_columns)
    def fetchone(self):
        row=self.cursor.fetchone();return self._row(row) if row is not None else None
    def fetchall(self):return [self._row(row) for row in self.cursor.fetchall()]
    def __iter__(self):return iter(self.fetchall())

class Connection:
    def __init__(self,connection):self.connection=connection;self.write_locked=False
    def execute(self,sql,args=()):
        if not self.write_locked and re.match(r'\s*(INSERT|UPDATE|DELETE|ALTER|CREATE|DROP|BEGIN IMMEDIATE)',sql,re.I):
            # Serialize short mutations (including schedule validation) across server processes.
            # Read transactions never acquire this exclusive lock.
            self.connection.execute('SELECT pg_advisory_xact_lock(77410312)')
            self.connection.execute("SELECT set_config('naryadai.service_write','1',true)")
            self.write_locked=True
        sql=postgres_sql(sql);match=re.match(r'INSERT INTO\s+(\w+)',sql,re.I)
        returning=bool(match and match[1] in TABLES_WITH_IDS and 'RETURNING' not in sql.upper())
        if returning:sql+=' RETURNING id'
        try:cur=self.connection.execute(sql,args or None)
        except psycopg.IntegrityError:raise sqlite3.IntegrityError('Нарушение ограничений базы.') from None
        row=cur.fetchone() if returning else None
        last=row['id'] if row else None
        return Cursor(cur,last)
    def executemany(self,sql,rows):
        for row in rows:self.execute(sql,row)
    def executescript(self,script):
        for sql in script.split(';'):
            if sql.strip():self.execute(postgres_ddl(sql))

class PostgresStore(ServerStore):
    def __init__(self,directory,settings,storage):
        self.settings=settings;self.seed_password=settings.bootstrap_password;self.storage=storage
        self._local=threading.local()
        self.pool=ConnectionPool(settings.database_url,min_size=0,max_size=settings.database_pool_size,timeout=15,
           kwargs={'row_factory':dict_row,'connect_timeout':10,'prepare_threshold':None},open=True)
        with self._connect() as conn:
            conn.execute('CREATE SCHEMA IF NOT EXISTS naryadai')
            conn.execute('REVOKE ALL ON SCHEMA naryadai FROM PUBLIC')
        super().__init__(directory,settings)
        with self.transaction() as c:
            for table in TABLES_WITH_IDS:
                c.execute(f"SELECT setval('naryadai.{table}_id_seq',GREATEST((SELECT last_value FROM naryadai.{table}_id_seq),(SELECT COALESCE(MAX(id),1) FROM {table})),true)")
            for row in c.execute("SELECT tablename FROM pg_tables WHERE schemaname='naryadai'"):
                table=row['tablename']
                if not re.fullmatch(r'[a-z_]+',table):raise ValueError('Недопустимое имя таблицы.')
                c.execute(f'ALTER TABLE {table} ENABLE ROW LEVEL SECURITY')
    def _connect(self):
        try:return psycopg.connect(self.settings.database_url,row_factory=dict_row,connect_timeout=10,prepare_threshold=None)
        except psycopg.Error:raise sqlite3.OperationalError('PostgreSQL недоступен. Проверьте настройки соединения.') from None
    @contextmanager
    def transaction(self,write=False):
        current=getattr(self._local,'connection',None)
        if current is not None:
            yield current;return
        try:
            with self.pool.connection() as conn:
                conn.execute('SET LOCAL search_path TO naryadai,public')
                conn.execute("SET LOCAL TIME ZONE 'Asia/Qyzylorda'")
                wrapped=Connection(conn)
                if write:wrapped.execute('BEGIN IMMEDIATE')
                self._local.connection=wrapped;self._local.after_commit=[]
                try:
                    yield wrapped
                    conn.commit()
                    for fn in self._local.after_commit:fn()
                except Exception:conn.rollback();raise
                finally:self._local.connection=None;self._local.after_commit=[]
        except psycopg.OperationalError:raise sqlite3.OperationalError('PostgreSQL временно недоступен.') from None
    def close(self):self.pool.close()
    def save_photo(self,p):
        import uuid
        target=self.photos/(uuid.uuid4().hex+p.suffix.lower());self.storage.upload(target.name,p.read_bytes());return target
    def remove_photo(self,p):self.storage.delete(p.name)
    def read_photo(self,name):return self.storage.download(name)

