Если нормы не переданы, не придумывай их. confidence (0–1) и quality_1_5 (1–5) — необязательные дополнительные поля.'''

class AIError(ValueError):pass

CHAT_PROMPT='''Ты помощник администратора приложения АО Костанайские минералы / НарядAI.
Отвечай на русском языке обычным понятным текстом. Помогай обсуждать производственные задачи,
отчёты и работу команды. Если информации недостаточно, уточняй. Не выдумывай сведения.
В history могут передаваться READ_ONLY_DATABASE_FACTS: проверенные агрегаты за указанную неделю и текущая доступность работников.
Используй только эти факты, называй период и ссылайся на номера нарядов. Сотрудники указаны по анонимному ID.
Для другого периода или отсутствующих показателей попроси сформировать сводку через API аналитики.
Ты не можешь менять наряды или оценки и выполнять SQL.
Не утверждай, что выполнил действие в приложении. Решения принимает человек.'''

def parse_verdict(text):
    if not isinstance(text,str) or not text.strip():raise AIError('AnythingLLM вернул пустой ответ.')
    text=re.sub(r'<think>.*?</think>','',text,flags=re.S).strip()
    if text.startswith('```'):
        text=re.sub(r'^```(?:json)?\s*','',text,flags=re.I);text=re.sub(r'\s*```$','',text)
    try:r=json.loads(text)
    except (ValueError,TypeError):raise AIError('Модель не вернула корректный JSON. Мастер может проверить отчёт вручную.')
    if not isinstance(r,dict) or type(r.get('score')) is not int or not 0<=r['score']<=100:
        raise AIError('В ответе модели отсутствует оценка 0–100.')
    if r.get('verdict') not in ('acceptable','needs_clarification','insufficient_data'):raise AIError('Неизвестный вердикт модели.')
    if not isinstance(r.get('summary'),str) or not 3<=len(r['summary'])<=3000:raise AIError('Модель не дала корректное пояснение.')
    findings=r.get('findings');criteria=r.get('criteria')
    if not isinstance(findings,list) or len(findings)>20 or any(not isinstance(v,str) or len(v)>1000 for v in findings):raise AIError('Некорректный список замечаний модели.')
    limits={'description':25,'matching':25,'verification':30,'materials_time':20}
    if not isinstance(criteria,dict) or set(criteria)!=set(limits) or any(type(criteria[k]) is not int or not 0<=criteria[k]<=v for k,v in limits.items()):raise AIError('Некорректные оценки критериев.')
    if sum(criteria.values())!=r['score']:raise AIError('Оценка модели не совпадает с суммой критериев.')
    result={k:r[k] for k in ('score','verdict','summary','findings','criteria')}
    if 'confidence' in r:
        if type(r['confidence']) not in (int,float) or not 0<=r['confidence']<=1:raise AIError('Некорректная уверенность модели.')
        result['confidence']=r['confidence']
    if 'quality_1_5' in r:
        if type(r['quality_1_5']) is not int or not 1<=r['quality_1_5']<=5:raise AIError('Некорректная оценка качества 1–5.')
        result['quality_1_5']=r['quality_1_5']
    return result

class AnythingLLM:
    def __init__(self,settings):self.settings=settings
    def request(self,path,payload=None):
        s=self.settings;body=json.dumps(payload,ensure_ascii=False).encode() if payload is not None else None
        req=Request(s.base_url+'/api/v1'+path,data=body,headers={'Authorization':'Bearer '+s.api_key,'Content-Type':'application/json'},method='POST' if body is not None else 'GET')
        try:
            with urlopen(req,timeout=s.timeout) as response:
                raw=response.read(2_000_001)
                if len(raw)>2_000_000:raise AIError('Ответ AnythingLLM слишком большой.')
                return json.loads(raw)
        except HTTPError as e:
            if e.code in (401,403):raise AIError('AnythingLLM отклонил API-ключ. Проверьте ключ в настройках сервера.') from None
            raise AIError(f'AnythingLLM вернул HTTP {e.code}. Проверьте workspace и выбранную модель.') from None
        except (URLError,TimeoutError,OSError):raise AIError('AnythingLLM недоступен или не ответил вовремя. Проверьте, что он запущен.') from None
        except (json.JSONDecodeError,UnicodeError):raise AIError('AnythingLLM вернул ответ в неподдерживаемом формате.') from None
    def check_workspace(self,slug=None):
        r=self.request('/workspace/'+quote(slug or self.settings.workspace,safe=''))
        if not isinstance(r,dict) or not r.get('workspace'):raise AIError('Рабочее пространство не найдено.')
        return r
    def workspaces(self):
        r=self.request('/workspaces')
        if not isinstance(r,dict) or not isinstance(r.get('workspaces'),list):raise AIError('Не удалось получить список рабочих пространств.')
        return [w for w in r['workspaces'] if isinstance(w,dict) and isinstance(w.get('slug'),str)]
    def create_workspace(self,name='NaryadAI — проверка отчётов',prompt=SYSTEM_PROMPT):
        r=self.request('/workspace/new',{'name':name,'openAiTemp':0.2,'openAiHistory':0,'openAiPrompt':prompt,'chatMode':'chat'})
        w=r.get('workspace') if isinstance(r,dict) else None
        if not isinstance(w,dict) or not isinstance(w.get('slug'),str) or not w['slug']:raise AIError('AnythingLLM не создал рабочее пространство.')
        return w['slug']
    def chat(self,message,history=None,conversation_id=''):
        slug=self.settings.chat_workspace
        if not slug or slug==self.settings.workspace:
            raise AIError('Настройте отдельное пространство чата через configure_server.bat.')
        # Контекст хранится в общей базе: смена ПК/модели не теряет диалог.
        # Свежая API-сессия исключает повторное добавление истории AnythingLLM.
        context={'history':history or [],'message':message}
        r=self.request('/workspace/'+quote(slug,safe='')+'/chat',
            {'message':CHAT_PROMPT+'\nДИАЛОГ:\n'+json.dumps(context,ensure_ascii=False),
             'mode':'chat','sessionId':'allur-chat-'+uuid.uuid4().hex})
        if not isinstance(r,dict) or r.get('type')=='abort' or r.get('error'):raise AIError('AnythingLLM не смог ответить в чате. Проверьте выбранную модель.')
        text=r.get('textResponse')
        if not isinstance(text,str):raise AIError('AnythingLLM вернул пустой ответ чата.')
        text=re.sub(r'<think>.*?</think>','',text,flags=re.S).strip()
        if not text or len(text)>20000:raise AIError('Ответ чата пустой или слишком большой. Попросите ответить короче.')
        return text
    def review(self,task,report,photos_dir):
        attachments=[]
        if self.settings.send_images:
            # Уменьшить изображения до 1280 px, чтобы не переполнять контекст и HTTP.
            from PIL import Image,ImageOps
            from io import BytesIO
            for name in report.get('before_photos',[])+report['photos']:
                p=Path(photos_dir)/Path(name).name
                try:
                    with Image.open(p) as im:
                        im=ImageOps.exif_transpose(im).convert('RGB');im.thumbnail((1280,1280));data=BytesIO();im.save(data,'JPEG',quality=80)
                except OSError:raise AIError('Фото отчёта не удалось открыть.') from None
                prefix='before-' if name in report.get('before_photos',[]) else 'after-'
                attachments.append({'name':prefix+p.stem+'.jpg','mime':'image/jpeg','contentString':'data:image/jpeg;base64,'+base64.b64encode(data.getvalue()).decode()})
        payload={'task':{k:task[k] for k in ('title','description','equipment','site','kind','duration')},
                 'report':{k:report[k] for k in ('work','result','defect','hours','materials')},
                 'norms':task.get('norms',{}),'photo_issues':report.get('photo_issues',[]),'before_photos_count':len(report.get('before_photos',[])),'photos_in_report':len(report['photos']),'photos_sent_to_model':len(attachments)}
        message=SYSTEM_PROMPT+'\nДАННЫЕ ДЛЯ ОЦЕНКИ:\n'+json.dumps(payload,ensure_ascii=False)
        # Отдельная сессия для каждого запроса: отчёты сотрудников не смешиваются.
        r=self.request('/workspace/'+quote(self.settings.workspace,safe='')+'/chat',
            {'message':message,'mode':'chat','sessionId':'naryadai-'+uuid.uuid4().hex,'attachments':attachments})
        if not isinstance(r,dict) or r.get('type')=='abort' or r.get('error'):raise AIError('AnythingLLM не смог обработать отчёт. Проверьте модель и поддержку фотографий.')
        return parse_verdict(r.get('textResponse'))

"""Долговечная очередь: ИИ на домашнем ПК сам забирает задания по HTTPS."""
import hmac,json,secrets,time
from app.store import now

class RemoteJobs:
    def __init__(self,store,settings):
        self.store=store;self.settings=settings
        with store.transaction() as c:
            for col,kind in [('lease_token','TEXT'),('lease_until','DOUBLE PRECISION'),('queued_at','DOUBLE PRECISION')]:
                # PostgreSQL и SQLite для сетевых тестов поддерживают разные ADD COLUMN.
                if settings.database_url:c.execute(f'ALTER TABLE ai_jobs ADD COLUMN IF NOT EXISTS {col} {kind}')
                elif col not in [r['name'] for r in c.execute('PRAGMA table_info(ai_jobs)')]:c.execute(f'ALTER TABLE ai_jobs ADD COLUMN {col} {kind}')
            c.execute('CREATE TABLE IF NOT EXISTS ai_worker_state(id INTEGER PRIMARY KEY,last_seen DOUBLE PRECISION NOT NULL)')
            if settings.database_url:c.execute('ALTER TABLE ai_worker_state ENABLE ROW LEVEL SECURITY')
            c.execute('UPDATE ai_jobs SET queued_at=? WHERE queued_at IS NULL',(time.time(),))
    def heartbeat(self,c=None):
        if c is None:
            with self.store.transaction() as conn:return self.heartbeat(conn)
        c.execute('INSERT INTO ai_worker_state VALUES(1,?) ON CONFLICT(id) DO UPDATE SET last_seen=excluded.last_seen',(time.time(),))
    def expire(self,c=None):
        if c is None:
            with self.store.transaction() as conn:return self.expire(conn)
        clock=time.time();state=c.execute('SELECT last_seen FROM ai_worker_state WHERE id=1').fetchone()
        offline=not state or clock-state['last_seen']>45
        for j in c.execute("SELECT report_id,status,lease_until,queued_at FROM ai_jobs WHERE status IN ('queued','processing')").fetchall():
            if j['status']=='processing' and (not self.settings.ai_enabled or (j['lease_until'] or 0)<clock):
                self.store.finish_ai(j['report_id'],None,'Обработчик ИИ не завершил проверку вовремя. Отчёт передан мастеру.',c=c)
            elif j['status']=='queued' and (not self.settings.ai_enabled or (offline and clock-(j['queued_at'] or clock)>=self.settings.offline_wait)):
                self.store.finish_ai(j['report_id'],None,'Обработчик ИИ выключен или не подключён. Отчёт передан мастеру.',c=c)
    def claim(self):
        with self.store.transaction() as c:
            c.execute('BEGIN IMMEDIATE');self.heartbeat(c);self.expire(c)
            j=c.execute("SELECT report_id FROM ai_jobs WHERE status='queued' ORDER BY report_id LIMIT 1").fetchone()
            if not j:return None
            rid=j['report_id'];lease=secrets.token_urlsafe(32)
            c.execute("UPDATE ai_jobs SET status='processing',lease_token=?,lease_until=? WHERE report_id=?",(lease,time.time()+660,rid))
            r=dict(c.execute('SELECT * FROM reports WHERE id=?',(rid,)).fetchone());t=dict(c.execute('SELECT * FROM tasks WHERE id=?',(r['task_id'],)).fetchone())
            for field in ('materials','photos'):r[field]=json.loads(r[field])
            t,r=self.store.ai_context(c,t,r)
            return {'report':r,'task':t,'lease':lease}
    def require_lease(self,c,rid,lease):
        j=c.execute('SELECT * FROM ai_jobs WHERE report_id=?',(rid,)).fetchone()
        if not j or j['status']!='processing' or not hmac.compare_digest(j['lease_token'] or '',lease) or (j['lease_until'] or 0)<time.time():
            raise ValueError('Задание уже завершено либо срок обработки истёк.')
    def result(self,rid,lease,result,error,model):
        with self.store.transaction() as c:
            c.execute('BEGIN IMMEDIATE');self.require_lease(c,rid,lease);self.heartbeat(c)
            c.execute('UPDATE ai_jobs SET model=? WHERE report_id=?',(model,rid))
            self.store.finish_ai(rid,result,error,c=c)
            c.execute('UPDATE ai_jobs SET lease_token=NULL,lease_until=NULL WHERE report_id=?',(rid,))

"""Обработчик на ПК с AnythingLLM. Подключения к серверу исходящие HTTPS."""
import json,logging,threading,time,tempfile
from pathlib import Path
from urllib.request import Request,urlopen
from urllib.error import HTTPError,URLError
from urllib.parse import urlparse,quote
from server.config import Settings
from server.anythingllm import AnythingLLM,AIError

ROOT=Path(__file__).resolve().parent
LOG=logging.getLogger('worker')

class Worker:
    def __init__(self,server,token,ai):
        p=urlparse(server)
        if p.scheme!='https' and not (p.scheme=='http' and p.hostname in ('127.0.0.1','localhost')):raise ValueError('Облачный адрес должен начинаться с https://.')
        if not p.hostname or p.username or p.password or p.query or p.fragment or p.path not in ('','/'):raise ValueError('Некорректный адрес сервера.')
        if len(token)<32:raise ValueError('Ключ обработчика ИИ должен содержать не меньше 32 символов.')
        self.server=server.rstrip('/');self.token=token;self.ai=ai;self._prefer_chat=False
    def request(self,path,payload=None,lease=None,binary=False):
        headers={'Authorization':'Bearer '+self.token,'Content-Type':'application/json'}
        if lease:headers['X-Job-Lease']=lease
        data=json.dumps(payload,ensure_ascii=False).encode() if payload is not None else None
        req=Request(self.server+path,data=data,headers=headers,method='POST' if data is not None else 'GET')
        try:
            with urlopen(req,timeout=90) as r:
                raw=r.read(10*1024*1024+1)
                if len(raw)>10*1024*1024:raise OSError('Ответ сервера слишком большой.')
                return raw if binary else json.loads(raw)
        except HTTPError as e:
            if e.code in (401,403):raise PermissionError('Сервер отклонил ключ обработчика ИИ.') from None
            if e.code==400:raise ValueError('Задание уже завершено либо сервер отклонил результат.') from None
            raise OSError(f'Сервер приложения вернул HTTP {e.code}.') from None
        except (URLError,TimeoutError):raise OSError('Сервер приложения пока недоступен; подключение будет повторено.') from None
    def run_once(self):
        if self._prefer_chat:
            self._prefer_chat=False
            if self.run_chat_once():return True
        job=self.request('/api/ai/claim',{})['job']
        if not job:return self.run_chat_once()
        self._prefer_chat=True
        report=job['report'];rid=report['id'];lease=job['lease'];result=None;error=''
        LOG.info('Получен отчёт ОТ-%04d',rid)
        with tempfile.TemporaryDirectory(prefix='naryadai-ai-') as folder:
            folder=Path(folder)
            try:
                if self.ai.settings.send_images:
                    for name in report.get('before_photos',[])+report['photos']:
                        if Path(name).name!=name:raise AIError('Некорректное имя фотографии.')
                        raw=self.request(f'/api/ai/photo/{rid}/'+quote(name,safe=''),lease=lease,binary=True)
                        (folder/name).write_bytes(raw)
                result=self.ai.review(job['task'],report,folder)
            except (AIError,OSError) as e:error=str(e)
            body={'lease':lease,'result':result,'error':error,'model':self.ai.settings.model_label[:200]}
            for attempt in range(3):
                try:self.request(f'/api/ai/result/{rid}',body);break
                except OSError:
                    if attempt==2:raise
                    time.sleep(2)
        LOG.info('Отчёт ОТ-%04d передан мастеру%s',rid,' с оценкой ИИ' if result else ' для ручной проверки')
        return True
    def run_chat_once(self):
        job=self.request('/api/ai/chat/claim',{})['job']
        if not job:return False
        LOG.info('Получено сообщение администратора')
        try:answer=self.ai.chat(job['message'],job['history'],job['conversation_id']);error=''
        except (AIError,OSError) as e:answer='';error=str(e)
        body={'lease':job['lease'],'answer':answer,'error':error,'model':self.ai.settings.model_label[:200]}
        for attempt in range(3):
            try:self.request('/api/ai/chat/result/'+job['id'],body);break
            except OSError:
                if attempt==2:raise
                time.sleep(2)
        LOG.info('Ответ чата передан в приложение')
        return True
    def run(self):
        stop=threading.Event()
        def heartbeat():
            while not stop.is_set():
                try:self.request('/api/ai/heartbeat',{})
                except (OSError,ValueError,PermissionError):pass
                stop.wait(15)
        threading.Thread(target=heartbeat,daemon=True).start()
        try:
            while True:
                try:busy=self.run_once()
                except PermissionError:raise
                except (OSError,ValueError) as e:LOG.warning('%s',e);busy=False
                if not busy:time.sleep(5)
        except KeyboardInterrupt:print('Обработчик остановлен.')
        finally:stop.set()

def main():
    cfg=ROOT/'worker_config.json'
    if not cfg.exists():raise ValueError('Сначала запустите configure_worker.bat.')
    data=json.loads(cfg.read_text(encoding='utf-8-sig'));settings=Settings.load()
    logging.basicConfig(level=logging.INFO,format='%(asctime)s %(message)s')
    Worker(data['server'],data['token'],AnythingLLM(settings)).run()

if __name__=='__main__':
    try:main()
    except (OSError,ValueError,PermissionError) as e:print('Обработчик ИИ:',e);raise SystemExit(1)

"""Case-1 business operations, shared by SQLite and PostgreSQL.

SQL is parameterized. Photos are staged before acquiring a database write lock.
Only the outer transaction commits; nested Store calls share that transaction.
"""
import hashlib
import json
import math
import secrets
import shutil
import sqlite3
import threading
from contextlib import contextmanager,closing
from datetime import date, datetime, timedelta
from decimal import Decimal
from pathlib import Path
from zoneinfo import ZoneInfo
from app.migrations import migrate

TZ=ZoneInfo('Asia/Qyzylorda')
ACTIVE=('available','planned','accepted','queued','rejected','inProgress','paused','revision','aiPending','submitted')
PRIORITIES={'urgent':'Аварийный','high':'Высокий','normal':'Обычный','scheduled':'Плановый'}

def stamp():return datetime.now(TZ).replace(tzinfo=None).isoformat(timespec='seconds')
def moment(value):
    result=datetime.fromisoformat(str(value))
    return result.astimezone(TZ).replace(tzinfo=None) if result.tzinfo else result
def decoded(value, default=None):
    return json.loads(value) if isinstance(value,str) else value if value is not None else default
def j(value):return json.dumps(value,ensure_ascii=False,allow_nan=False)

class SQLiteConnection:
    def __init__(self,raw):self.raw=raw
    def execute(self,sql,args=()):
        if sql.strip().upper().startswith('BEGIN IMMEDIATE') and self.raw.in_transaction:sql='SELECT 1'
        return self.raw.execute(sql,args)
    def executemany(self,sql,rows):return self.raw.executemany(sql,rows)
    def executescript(self,script):
        # sqlite3.executescript commits implicitly. DDL here contains no trigger bodies.
        for sql in script.split(';'):
            if sql.strip():self.execute(sql)

class CaseWorkflow:
    def __init__(self,*args,**kwargs):
        self._local=threading.local()
        super().__init__(*args,**kwargs)
        if not getattr(getattr(self,'settings',None),'database_url',''):
            with closing(sqlite3.connect(self.path)) as raw:raw.execute('PRAGMA journal_mode=WAL')

    def migrate_case(self):
        postgres=bool(getattr(getattr(self,'settings',None),'database_url',''))
        if postgres:
            with self.transaction(write=True) as c:migrate(c.connection,True)
            return
        if self.path.exists() and self.path.stat().st_size:
            backup=self.directory/'naryadai-before-v2.db'
            if not backup.exists():
                with closing(sqlite3.connect(self.path)) as source,closing(sqlite3.connect(backup)) as target:source.backup(target)
        # SQLite cannot DROP inline constraints. Preserve IDs, extra columns, manual indexes and triggers.
        import re
        with closing(sqlite3.connect(self.path,timeout=15)) as raw:
            raw.row_factory=sqlite3.Row;raw.execute('PRAGMA legacy_alter_table=ON');raw.execute('BEGIN IMMEDIATE')
            try:
                for table in ('equipment','reports','tasks','users','shift_rules','shifts'):
                    found=raw.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name=?",(table,)).fetchone()
                    if not found:continue
                    original=found['sql'];definition=original
                    if table=='equipment':definition=re.sub(r'\bname(\s+TEXT)\s+UNIQUE\b',r'name\1',definition,flags=re.I)
                    elif table=='reports':definition=re.sub(r',\s*FOREIGN KEY\s*\(\s*task_id\s*,\s*worker_id\s*\)\s+REFERENCES\s+tasks\s*\(\s*id\s*,\s*worker_id\s*\)', '',definition,flags=re.I)
                    elif table=='tasks':
                        definition=definition.replace("priority IN ('urgent','normal')","priority IN ('urgent','high','normal','scheduled')")
                        definition=definition.replace("status IN ('available','planned','inProgress','paused','aiPending','submitted','approved','revision','cancelled')","status IN ('available','planned','accepted','queued','rejected','inProgress','paused','aiPending','submitted','approved','revision','cancelled')")
                        definition=definition.replace('start>=0 AND start<24','start>=0 AND start<48').replace('start+duration<=24','start+duration<=48')
                    elif table=='users':definition=definition.replace("role IN ('worker','master','admin')","role IN ('worker','master','admin','manager')")
                    else:definition=definition.replace('start>=0 AND start<"end" AND "end"<24','start>=0 AND start<24 AND "end">start AND "end"<=start+24')
                    if definition==original:continue
                    extras=[r['sql'] for r in raw.execute("SELECT sql FROM sqlite_master WHERE tbl_name=? AND type IN ('trigger','index') AND sql IS NOT NULL",(table,))]
                    definition=re.sub(r'CREATE TABLE(?: IF NOT EXISTS)?\s+'+table+r'\b','CREATE TABLE '+table+'_v2',definition,flags=re.I)
                    raw.execute(definition);raw.execute('INSERT INTO '+table+'_v2 SELECT * FROM '+table);raw.execute('DROP TABLE '+table);raw.execute('ALTER TABLE '+table+'_v2 RENAME TO '+table)
                    for sql in extras:raw.execute(sql)
                migrate(raw,False)
                if raw.execute('PRAGMA foreign_key_check').fetchone():raise ValueError('SQLite migration failed foreign-key validation; the original database was preserved.')
                raw.commit()
            except Exception:raw.rollback();raise

    @contextmanager
    def transaction(self,write=False):
        current=getattr(self._local,'connection',None)
        if current is not None:
            yield current;return
        raw=sqlite3.connect(self.path,timeout=15);raw.row_factory=sqlite3.Row
        raw.execute('PRAGMA foreign_keys=ON');raw.execute('BEGIN IMMEDIATE' if write else 'BEGIN')
        self._local.connection=SQLiteConnection(raw);self._local.after_commit=[]
        try:
            yield self._local.connection
            raw.commit()
            for fn in self._local.after_commit:fn()
        except Exception:
            raw.rollback();raise
        finally:self._local.connection=None;self._local.after_commit=[];raw.close()

    def close(self):pass

